<script lang="ts" setup>
import type { CooperationStatus, Customer, CustomerAddress, CustomerAddressForm, CustomerCategoryForm, CustomerCategoryTreeNode, CustomerContact, CustomerContactForm, CustomerForm, CustomerType, MasterStatus } from '../api';

import { computed, onMounted, reactive, ref } from 'vue';
import { Page } from '@vben/common-ui';
import { message } from 'antdv-next';
import { $t } from '#/locales';
import { createCustomerAddressApi, createCustomerApi, createCustomerCategoryApi, createCustomerContactApi, getCustomerAddressesApi, getCustomerApi, getCustomerCategoryTreeApi, getCustomerContactsApi, getCustomerListApi, setDefaultAddressApi, setPrimaryContactApi, updateCooperationStatusApi, updateCustomerAddressApi, updateCustomerApi, updateCustomerCategoryApi, updateCustomerContactApi, updateCustomerStatusApi } from '../api';

interface TreeNode extends CustomerCategoryTreeNode { key: string; title: string; children: TreeNode[]; }
interface PageData { items: Customer[]; page: number; size: number; total: number; total_pages: number; links: Record<string, unknown>; }

const emptyPage = (): PageData => ({ items: [], page: 1, size: 20, total: 0, total_pages: 0, links: {} });
const emptyCustomer = (): CustomerForm => ({ customer_code: '', customer_name: '', customer_type: 'ENTERPRISE', status: 'ACTIVE', cooperation_status: 'NORMAL', sales_enabled: true, shipment_enabled: true, trace_enabled: true, preferred: false });
const emptyCategory = (): CustomerCategoryForm => ({ category_code: '', category_name: '', status: 'ACTIVE', sort_no: 0 });
const emptyContact = (): CustomerContactForm => ({ contact_name: '', contact_type: 'BUSINESS', is_primary: false, status: 'ACTIVE' });
const emptyAddress = (): CustomerAddressForm => ({ address_code: '', address_name: '', address_type: 'DELIVERY', country: '', province: '', city: '', district: '', detail_address: '', is_default: false, status: 'ACTIVE' });

const tree = ref<TreeNode[]>([]); const selectedCategory = ref<number>(); const selectedCustomer = ref<Customer>(); const detailLoading = ref(false); const loading = ref(false); const pageData = ref<PageData>(emptyPage());
const contacts = ref<CustomerContact[]>([]); const addresses = ref<CustomerAddress[]>([]); const customerDrawer = ref(false); const categoryModal = ref(false); const contactModal = ref(false); const addressModal = ref(false); const saving = ref(false);
const customerForm = ref<CustomerForm>(emptyCustomer()); const categoryForm = ref<CustomerCategoryForm>(emptyCategory()); const contactForm = ref<CustomerContactForm>(emptyContact()); const addressForm = ref<CustomerAddressForm>(emptyAddress());
const filters = reactive<{ keyword: string; customer_type?: CustomerType; status?: MasterStatus; cooperation_status?: CooperationStatus }>({ keyword: '' });
const customerTypes = computed(() => ['ENTERPRISE', 'DISTRIBUTOR', 'END_CUSTOMER', 'INTERNAL', 'OTHER'].map((value) => ({ label: value, value })));
const categoryOptions = computed(() => {
  const map = (nodes: TreeNode[]): Array<{ children: any[]; disabled: boolean; title: string; value: number }> => nodes.map((node) => ({ title: `${node.name} (${node.code})`, value: node.id, disabled: node.status !== 'ACTIVE', children: map(node.children) }));
  return map(tree.value);
});
const columns = computed(() => [
  { title: '编码', dataIndex: 'customer_code', key: 'customer_code', width: 130 }, { title: '客户名称', dataIndex: 'customer_name', key: 'customer_name', width: 180 }, { title: '分类', dataIndex: 'category_name', key: 'category_name', width: 100 }, { title: '类型', dataIndex: 'customer_type', key: 'customer_type', width: 110 }, { title: '国家/地区', dataIndex: 'country', key: 'country', width: 100 }, { title: $t('customer.status'), dataIndex: 'status', key: 'status', width: 75 }, { title: $t('customer.cooperation'), dataIndex: 'cooperation_status', key: 'cooperation_status', width: 90 },
]);

function mapTree(nodes: CustomerCategoryTreeNode[]): TreeNode[] { return nodes.map((node) => ({ ...node, key: String(node.id), title: `${node.name} (${node.code})`, children: mapTree(node.children || []) })); }
function findNode(id: number, nodes = tree.value): TreeNode | undefined { for (const node of nodes) { if (node.id === id) return node; const found = findNode(id, node.children); if (found) return found; } }
function labelStatus(status: MasterStatus) { return status === 'ACTIVE' ? $t('customer.active') : $t('customer.disabled'); }
function statusColor(status: MasterStatus) { return status === 'ACTIVE' ? 'green' : 'default'; }
function cooperationColor(status: CooperationStatus) { return status === 'NORMAL' ? 'green' : status === 'SUSPENDED' ? 'orange' : 'red'; }

async function loadTree() { tree.value = mapTree(await getCustomerCategoryTreeApi()); }
async function loadCustomers(page = 1, size = pageData.value.size) { loading.value = true; try { const data = await getCustomerListApi({ page, size, keyword: filters.keyword.trim() || undefined, category_id: selectedCategory.value, customer_type: filters.customer_type, status: filters.status, cooperation_status: filters.cooperation_status }); pageData.value = data; const current = data.items.find((item) => item.id === selectedCustomer.value?.id) || data.items[0]; if (current) await selectCustomer(current); else { selectedCustomer.value = undefined; contacts.value = []; addresses.value = []; } } finally { loading.value = false; } }
async function selectCustomer(item: Customer) { detailLoading.value = true; try { const [customer, contactData, addressData] = await Promise.all([getCustomerApi(item.id), getCustomerContactsApi(item.id), getCustomerAddressesApi(item.id)]); selectedCustomer.value = customer; contacts.value = contactData; addresses.value = addressData; } finally { detailLoading.value = false; } }
function selectTree(keys: Array<number | string>) { selectedCategory.value = keys[0] ? Number(keys[0]) : undefined; loadCustomers(1); }
function resetFilters() { filters.keyword = ''; filters.customer_type = undefined; filters.status = undefined; filters.cooperation_status = undefined; loadCustomers(1); }
function openCustomer(item?: Customer) { customerForm.value = item ? { ...item } : { ...emptyCustomer(), category_id: selectedCategory.value }; customerDrawer.value = true; }
async function saveCustomer() { if (!customerForm.value.customer_code.trim() || !customerForm.value.customer_name.trim()) { message.warning('请填写客户编码和客户名称'); return; } saving.value = true; try { const saved = customerForm.value.id ? await updateCustomerApi(customerForm.value.id, customerForm.value) : await createCustomerApi(customerForm.value); customerDrawer.value = false; await loadCustomers(pageData.value.page); await selectCustomer(saved); message.success($t('customer.save')); } finally { saving.value = false; } }
function openCategory() { const node = selectedCategory.value ? findNode(selectedCategory.value) : undefined; categoryForm.value = node ? { id: node.id, category_code: node.code, category_name: node.name, parent_id: node.parent_id, status: node.status, sort_no: node.sort_no, remark: node.remark } : emptyCategory(); categoryModal.value = true; }
async function saveCategory() { if (!categoryForm.value.category_code || !categoryForm.value.category_name) return; const saved = categoryForm.value.id ? await updateCustomerCategoryApi(categoryForm.value.id, categoryForm.value) : await createCustomerCategoryApi(categoryForm.value); categoryModal.value = false; selectedCategory.value = saved.id; await loadTree(); await loadCustomers(1); }
function openContact(item?: CustomerContact) { contactForm.value = item ? { ...item } : emptyContact(); contactModal.value = true; }
async function saveContact() { if (!selectedCustomer.value || !contactForm.value.contact_name.trim()) return; const saved = contactForm.value.id ? await updateCustomerContactApi(selectedCustomer.value.id, contactForm.value.id, contactForm.value) : await createCustomerContactApi(selectedCustomer.value.id, contactForm.value); contactModal.value = false; contacts.value = await getCustomerContactsApi(selectedCustomer.value.id); message.success(saved.is_primary ? '已设置主联系人' : $t('customer.save')); }
async function primaryContact(item: CustomerContact) { if (!selectedCustomer.value) return; await setPrimaryContactApi(selectedCustomer.value.id, item.id); contacts.value = await getCustomerContactsApi(selectedCustomer.value.id); }
function openAddress(item?: CustomerAddress) { addressForm.value = item ? { ...item } : emptyAddress(); addressModal.value = true; }
async function saveAddress() { if (!selectedCustomer.value || !addressForm.value.address_code.trim() || !addressForm.value.address_name.trim() || !addressForm.value.country.trim() || !addressForm.value.province.trim() || !addressForm.value.city.trim() || !addressForm.value.district.trim() || !addressForm.value.detail_address.trim()) { message.warning('请填写地址必填项'); return; } const saved = addressForm.value.id ? await updateCustomerAddressApi(selectedCustomer.value.id, addressForm.value.id, addressForm.value) : await createCustomerAddressApi(selectedCustomer.value.id, addressForm.value); addressModal.value = false; addresses.value = await getCustomerAddressesApi(selectedCustomer.value.id); if (saved.is_default) selectedCustomer.value = await getCustomerApi(selectedCustomer.value.id); }
async function defaultAddress(item: CustomerAddress) { if (!selectedCustomer.value) return; await setDefaultAddressApi(selectedCustomer.value.id, item.id); addresses.value = await getCustomerAddressesApi(selectedCustomer.value.id); selectedCustomer.value = await getCustomerApi(selectedCustomer.value.id); }
async function toggleStatus() { if (!selectedCustomer.value) return; selectedCustomer.value = await updateCustomerStatusApi(selectedCustomer.value.id, selectedCustomer.value.status === 'ACTIVE' ? 'DISABLED' : 'ACTIVE'); await loadCustomers(pageData.value.page); }
async function changeCooperation(value: CooperationStatus) { if (!selectedCustomer.value) return; selectedCustomer.value = await updateCooperationStatusApi(selectedCustomer.value.id, value); await loadCustomers(pageData.value.page); }

onMounted(async () => { await loadTree(); await loadCustomers(); });
</script>

<template>
  <Page auto-content-height>
    <div class="flex h-full min-h-0 gap-3">
      <a-card class="w-64 shrink-0" :body-style="{ padding: '12px' }">
        <template #title>{{ $t('customer.category') }}</template>
        <template #extra><a-button size="small" type="link" @click="openCategory">{{ $t('customer.edit') }}</a-button></template>
        <a-button block class="mb-3" size="small" @click="selectedCategory = undefined; loadCustomers(1)">{{ $t('customer.all') }}</a-button>
        <a-tree :default-expand-all="true" :selected-keys="selectedCategory ? [String(selectedCategory)] : []" :tree-data="tree" block-node @select="selectTree" />
        <a-button block class="mt-3" size="small" @click="categoryForm = emptyCategory(); categoryModal = true">{{ $t('customer.add') }}{{ $t('customer.category') }}</a-button>
      </a-card>

      <a-card class="min-w-0 flex-1" :body-style="{ padding: '12px' }">
        <template #title>{{ $t('customer.customer') }} <span class="ml-2 text-sm text-muted-foreground">{{ pageData.total }}</span></template>
        <template #extra><a-button type="primary" @click="openCustomer()">{{ $t('customer.add') }}</a-button></template>
        <div class="mb-3 flex flex-wrap gap-2"><a-input-search v-model:value="filters.keyword" allow-clear class="w-52" placeholder="编码 / 名称 / 税号" @search="loadCustomers(1)" /><a-select v-model:value="filters.customer_type" allow-clear class="w-32" :options="customerTypes" placeholder="客户类型" @change="loadCustomers(1)" /><a-select v-model:value="filters.status" allow-clear class="w-24" :options="[{ label: $t('customer.active'), value: 'ACTIVE' }, { label: $t('customer.disabled'), value: 'DISABLED' }]" :placeholder="$t('customer.status')" @change="loadCustomers(1)" /><a-select v-model:value="filters.cooperation_status" allow-clear class="w-28" :options="['NORMAL', 'SUSPENDED', 'BLOCKED'].map((value) => ({ label: $t(`customer.${value}`), value }))" :placeholder="$t('customer.cooperation')" @change="loadCustomers(1)" /><a-button @click="resetFilters">重置</a-button></div>
        <a-table :columns="columns" :data-source="pageData.items" :loading="loading" :pagination="false" :row-key="(record: Customer) => record.id" :row-class-name="(record: Customer) => record.id === selectedCustomer?.id ? 'bg-primary/5' : ''" :scroll="{ x: 880 }" size="small"><template #bodyCell="{ column, record }"><template v-if="column.key === 'customer_code'"><a-button class="h-auto p-0" type="link" @click="selectCustomer(record)">{{ record.customer_code }}</a-button></template><template v-else-if="column.key === 'status'"><a-tag :color="statusColor(record.status)">{{ labelStatus(record.status) }}</a-tag></template><template v-else-if="column.key === 'cooperation_status'"><a-tag :color="cooperationColor(record.cooperation_status)">{{ $t(`customer.${record.cooperation_status}`) }}</a-tag></template><template v-else-if="column.key === 'category_name'">{{ record.category_name || '-' }}</template></template></a-table>
        <div class="mt-3 flex justify-end"><a-pagination :current="pageData.page" :page-size="pageData.size" :page-size-options="['20', '50', '100']" :show-size-changer="true" :total="pageData.total" @change="(page, size) => loadCustomers(page, size)" /></div>
      </a-card>

      <a-card class="w-[430px] shrink-0" :body-style="{ padding: '12px' }" :loading="detailLoading"><template #title>{{ $t('customer.customer') }}</template><template #extra><a-space v-if="selectedCustomer"><a-button size="small" @click="openCustomer(selectedCustomer)">{{ $t('customer.edit') }}</a-button><a-button size="small" :danger="selectedCustomer.status === 'ACTIVE'" @click="toggleStatus">{{ selectedCustomer.status === 'ACTIVE' ? $t('customer.disabled') : $t('customer.active') }}</a-button></a-space></template>
        <a-empty v-if="!selectedCustomer" description="请选择客户" />
        <a-tabs v-else size="small"><a-tab-pane key="basic" :tab="$t('customer.basic')"><div class="mb-3 rounded bg-muted/40 p-3"><div class="text-lg font-semibold">{{ selectedCustomer.customer_name }}</div><div class="text-muted-foreground">{{ selectedCustomer.customer_code }} · {{ selectedCustomer.short_name || '-' }}</div><a-tag class="mt-2" :color="statusColor(selectedCustomer.status)">{{ labelStatus(selectedCustomer.status) }}</a-tag></div><a-descriptions :column="1" size="small"><a-descriptions-item label="分类">{{ selectedCustomer.category_name || '-' }}</a-descriptions-item><a-descriptions-item label="客户类型">{{ selectedCustomer.customer_type }}</a-descriptions-item><a-descriptions-item label="统一社会信用代码">{{ selectedCustomer.unified_social_credit_code || '-' }}</a-descriptions-item><a-descriptions-item label="税号">{{ selectedCustomer.tax_number || '-' }}</a-descriptions-item><a-descriptions-item label="注册地">{{ [selectedCustomer.country, selectedCustomer.province, selectedCustomer.city].filter(Boolean).join(' ') || '-' }}</a-descriptions-item><a-descriptions-item label="注册地址">{{ selectedCustomer.registered_address || '-' }}</a-descriptions-item></a-descriptions></a-tab-pane>
          <a-tab-pane key="business" :tab="$t('customer.business')"><a-descriptions :column="1" size="small"><a-descriptions-item :label="$t('customer.cooperation')"><a-select :value="selectedCustomer.cooperation_status" class="w-32" :options="['NORMAL', 'SUSPENDED', 'BLOCKED'].map((value) => ({ label: $t(`customer.${value}`), value }))" @change="changeCooperation" /></a-descriptions-item><a-descriptions-item label="销售可用"><a-switch :checked="selectedCustomer.sales_enabled" disabled /></a-descriptions-item><a-descriptions-item label="发货可用"><a-switch :checked="selectedCustomer.shipment_enabled" disabled /></a-descriptions-item><a-descriptions-item label="追溯可用"><a-switch :checked="selectedCustomer.trace_enabled" disabled /></a-descriptions-item><a-descriptions-item label="优选客户"><a-switch :checked="selectedCustomer.preferred" disabled /></a-descriptions-item><a-descriptions-item label="币种">{{ selectedCustomer.default_currency || '-' }}</a-descriptions-item><a-descriptions-item label="付款条件">{{ selectedCustomer.payment_term || '-' }}</a-descriptions-item><a-descriptions-item label="交付条件">{{ selectedCustomer.delivery_term || '-' }}</a-descriptions-item></a-descriptions></a-tab-pane>
          <a-tab-pane key="contacts" :tab="`${$t('customer.contacts')} (${contacts.length})`"><a-button block class="mb-2" size="small" @click="openContact()">{{ $t('customer.add') }}{{ $t('customer.contact') }}</a-button><a-list :data-source="contacts" size="small"><template #renderItem="{ item }"><a-list-item><a-list-item-meta :description="[item.department, item.position, item.mobile || item.phone, item.email].filter(Boolean).join(' · ')"><template #title>{{ item.contact_name }} <a-tag v-if="item.is_primary" color="green">{{ $t('customer.primary') }}</a-tag><a-tag v-if="item.status === 'DISABLED'">{{ $t('customer.disabled') }}</a-tag></template></a-list-item-meta><template #actions><a-button size="small" type="link" @click="openContact(item)">{{ $t('customer.edit') }}</a-button><a-button v-if="!item.is_primary && item.status === 'ACTIVE'" size="small" type="link" @click="primaryContact(item)">{{ $t('customer.primary') }}</a-button></template></a-list-item></template></a-list></a-tab-pane>
          <a-tab-pane key="addresses" :tab="`${$t('customer.addresses')} (${addresses.length})`"><a-button block class="mb-2" size="small" @click="openAddress()">{{ $t('customer.add') }}{{ $t('customer.address') }}</a-button><a-list :data-source="addresses" size="small"><template #renderItem="{ item }"><a-list-item><a-list-item-meta :description="item.full_address"><template #title>{{ item.address_name }} <a-tag>{{ item.address_type }}</a-tag><a-tag v-if="item.is_default" color="green">{{ $t('customer.default') }}</a-tag></template></a-list-item-meta><template #actions><a-button size="small" type="link" @click="openAddress(item)">{{ $t('customer.edit') }}</a-button><a-button v-if="!item.is_default && item.address_type === 'DELIVERY' && item.status === 'ACTIVE'" size="small" type="link" @click="defaultAddress(item)">{{ $t('customer.default') }}</a-button></template></a-list-item></template></a-list></a-tab-pane>
        </a-tabs>
      </a-card>
    </div>

    <a-drawer v-model:open="customerDrawer" :title="customerForm.id ? $t('customer.edit') : $t('customer.add')" :width="720"><a-form layout="vertical"><a-row :gutter="16"><a-col :span="12"><a-form-item label="客户编码" required><a-input v-model:value="customerForm.customer_code" /></a-form-item></a-col><a-col :span="12"><a-form-item label="客户名称" required><a-input v-model:value="customerForm.customer_name" /></a-form-item></a-col><a-col :span="12"><a-form-item label="简称"><a-input v-model:value="customerForm.short_name" /></a-form-item></a-col><a-col :span="12"><a-form-item label="分类"><a-tree-select v-model:value="customerForm.category_id" allow-clear class="w-full" tree-default-expand-all :tree-data="categoryOptions" /></a-form-item></a-col><a-col :span="12"><a-form-item label="客户类型"><a-select v-model:value="customerForm.customer_type" :options="customerTypes" /></a-form-item></a-col><a-col :span="12"><a-form-item label="主体类型"><a-select v-model:value="customerForm.company_type" allow-clear :options="['COMPANY','INDIVIDUAL','ORGANIZATION'].map((value) => ({ label: value, value }))" /></a-form-item></a-col><a-col :span="12"><a-form-item label="统一社会信用代码"><a-input v-model:value="customerForm.unified_social_credit_code" /></a-form-item></a-col><a-col :span="12"><a-form-item label="税号"><a-input v-model:value="customerForm.tax_number" /></a-form-item></a-col><a-col :span="8"><a-form-item label="国家/地区"><a-input v-model:value="customerForm.country" /></a-form-item></a-col><a-col :span="8"><a-form-item label="省份"><a-input v-model:value="customerForm.province" /></a-form-item></a-col><a-col :span="8"><a-form-item label="城市"><a-input v-model:value="customerForm.city" /></a-form-item></a-col><a-col :span="24"><a-form-item label="注册地址"><a-input v-model:value="customerForm.registered_address" /></a-form-item></a-col><a-col :span="8"><a-form-item label="销售可用"><a-switch v-model:checked="customerForm.sales_enabled" /></a-form-item></a-col><a-col :span="8"><a-form-item label="发货可用"><a-switch v-model:checked="customerForm.shipment_enabled" /></a-form-item></a-col><a-col :span="8"><a-form-item label="追溯可用"><a-switch v-model:checked="customerForm.trace_enabled" /></a-form-item></a-col><a-col :span="8"><a-form-item label="优选客户"><a-switch v-model:checked="customerForm.preferred" /></a-form-item></a-col><a-col :span="8"><a-form-item label="默认币种"><a-input v-model:value="customerForm.default_currency" /></a-form-item></a-col><a-col :span="8"><a-form-item label="合作状态"><a-select v-model:value="customerForm.cooperation_status" :options="['NORMAL','SUSPENDED','BLOCKED'].map((value) => ({ label: $t(`customer.${value}`), value }))" /></a-form-item></a-col><a-col :span="12"><a-form-item label="付款条件"><a-input v-model:value="customerForm.payment_term" /></a-form-item></a-col><a-col :span="12"><a-form-item label="交付条件"><a-input v-model:value="customerForm.delivery_term" /></a-form-item></a-col><a-col :span="24"><a-form-item label="备注"><a-textarea v-model:value="customerForm.remark" :rows="3" /></a-form-item></a-col></a-row></a-form><template #footer><div class="flex justify-end gap-2"><a-button @click="customerDrawer = false">{{ $t('customer.cancel') }}</a-button><a-button type="primary" :loading="saving" @click="saveCustomer">{{ $t('customer.save') }}</a-button></div></template></a-drawer>
    <a-modal v-model:open="categoryModal" :title="$t('customer.category')" @ok="saveCategory"><a-form layout="vertical"><a-form-item label="分类编码" required><a-input v-model:value="categoryForm.category_code" /></a-form-item><a-form-item label="分类名称" required><a-input v-model:value="categoryForm.category_name" /></a-form-item><a-form-item label="上级分类"><a-tree-select v-model:value="categoryForm.parent_id" allow-clear class="w-full" tree-default-expand-all :tree-data="categoryOptions" /></a-form-item><a-form-item label="状态"><a-select v-model:value="categoryForm.status" :options="[{ label: $t('customer.active'), value: 'ACTIVE' }, { label: $t('customer.disabled'), value: 'DISABLED' }]" /></a-form-item><a-form-item label="排序"><a-input-number v-model:value="categoryForm.sort_no" class="w-full" /></a-form-item></a-form></a-modal>
    <a-modal v-model:open="contactModal" :title="$t('customer.contact')" @ok="saveContact"><a-form layout="vertical"><a-row :gutter="12"><a-col :span="12"><a-form-item label="姓名" required><a-input v-model:value="contactForm.contact_name" /></a-form-item></a-col><a-col :span="12"><a-form-item label="类型"><a-select v-model:value="contactForm.contact_type" :options="['BUSINESS','PURCHASE','RECEIVING','QUALITY','TECHNICAL','FINANCE','AFTER_SALES','OTHER'].map((value) => ({ label: value, value }))" /></a-form-item></a-col><a-col :span="12"><a-form-item label="部门"><a-input v-model:value="contactForm.department" /></a-form-item></a-col><a-col :span="12"><a-form-item label="岗位"><a-input v-model:value="contactForm.position" /></a-form-item></a-col><a-col :span="12"><a-form-item label="手机"><a-input v-model:value="contactForm.mobile" /></a-form-item></a-col><a-col :span="12"><a-form-item label="邮箱"><a-input v-model:value="contactForm.email" /></a-form-item></a-col><a-col :span="12"><a-form-item label="主联系人"><a-switch v-model:checked="contactForm.is_primary" /></a-form-item></a-col><a-col :span="12"><a-form-item label="状态"><a-select v-model:value="contactForm.status" :options="[{ label: $t('customer.active'), value: 'ACTIVE' }, { label: $t('customer.disabled'), value: 'DISABLED' }]" /></a-form-item></a-col></a-row></a-form></a-modal>
    <a-modal v-model:open="addressModal" :title="$t('customer.address')" :width="680" @ok="saveAddress"><a-form layout="vertical"><a-row :gutter="12"><a-col :span="12"><a-form-item label="地址编码" required><a-input v-model:value="addressForm.address_code" /></a-form-item></a-col><a-col :span="12"><a-form-item label="地址名称" required><a-input v-model:value="addressForm.address_name" /></a-form-item></a-col><a-col :span="12"><a-form-item label="地址类型"><a-select v-model:value="addressForm.address_type" :options="['DELIVERY','REGISTERED','OFFICE','RETURN','BILLING','OTHER'].map((value) => ({ label: value, value }))" /></a-form-item></a-col><a-col :span="12"><a-form-item label="默认收货地址"><a-switch v-model:checked="addressForm.is_default" :disabled="addressForm.address_type !== 'DELIVERY'" /></a-form-item></a-col><a-col :span="6"><a-form-item label="国家" required><a-input v-model:value="addressForm.country" /></a-form-item></a-col><a-col :span="6"><a-form-item label="省" required><a-input v-model:value="addressForm.province" /></a-form-item></a-col><a-col :span="6"><a-form-item label="市" required><a-input v-model:value="addressForm.city" /></a-form-item></a-col><a-col :span="6"><a-form-item label="区县" required><a-input v-model:value="addressForm.district" /></a-form-item></a-col><a-col :span="24"><a-form-item label="详细地址" required><a-input v-model:value="addressForm.detail_address" /></a-form-item></a-col><a-col :span="12"><a-form-item label="收货联系人"><a-input v-model:value="addressForm.contact_name" /></a-form-item></a-col><a-col :span="12"><a-form-item label="联系电话"><a-input v-model:value="addressForm.contact_phone" /></a-form-item></a-col></a-row></a-form></a-modal>
  </Page>
